steps.script:
# ai_move_cover's board (exam mv05's position): Custodian Guard B in a line
# 2.2" north of obj_nml_1's dense ruin (area-large-2), P2's Custodian Guard A
# in the open far south, every other unit parked in the corners.
var st = GameState.state
var g = st.units.U_CUSTODIAN_GUARD_B
var k = 0
for m in g.models:
	m.position = {"x": 1430.0 + float(k) * 65.0, "y": 400.0}
	k += 1
if g.has("flags"):
	g.flags.erase("last_shot_idx")
	g.flags.erase("shot_recently")
var s = st.units.U_CUSTODIAN_GUARD_A_P2
var j = 0
for m in s.models:
	m.position = {"x": 1440.0 + float(j) * 65.0, "y": 1560.0}
	j += 1
var p1 = 0
var p2 = 0
for uid in st.units:
	if uid == "U_CUSTODIAN_GUARD_B" or uid == "U_CUSTODIAN_GUARD_A_P2":
		continue
	var u = st.units[uid]
	for m in u.get("models", []):
		if m.get("position") == null:
			continue
		if int(u.get("owner", 0)) == 1:
			m.position = {"x": 50.0 + 70.0 * float(p1 % 6), "y": 50.0 + 70.0 * float(p1 / 6)}
			p1 += 1
		else:
			m.position = {"x": 1300.0 + 70.0 * float(p2 % 6), "y": 2320.0 - 70.0 * float(p2 / 6)}
			p2 += 1
return TerrainManager.area_at(Vector2(1500.0, 750.0)).get("id", "")

# The Hidden weights ship OFF (neutral): load the opt-in profile that turns
# them on (WEIGHT_HIDDEN_GAINED 4.0, HIDDEN_WINDOW_BONUS 1.25), AFTER
# configure() (configure wipes profiles).
var f = FileAccess.open("res://tests/bench_profiles/yt_findings_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
return float(prof.parameters.get("WEIGHT_HIDDEN_GAINED", 0.0)) * 10.0 + float(prof.parameters.get("HIDDEN_WINDOW_BONUS", 1.0))

# ENGINE: the squad's approach end inside the ruin is Hidden in the
# enemy's next turn (13.09; a probe model at obj_nml_1's marker).
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var probe = u.models[0].duplicate(true)
probe["position"] = {"x": 1500.0, "y": 750.0}
return TerrainManager.is_model_hidden_at(probe, u, int(GameState.get_player_turn_index()) + 1)

var d_best = tree.current_scene._ai_suggestion_panel._decision
var best = 0.0
for r in d_best.get("_ai_decision_records", []):
	for c in r.get("candidates", []):
		var bd = c.get("score_breakdown", {})
		if bd is Dictionary and bd.has("hidden_gain"):
			best = maxf(best, float(bd["hidden_gain"]))
return best

# Every option's '▸ details' link, through the panel's own handler
# (toggle_section, what clicking the link calls), then the text it now shows:
# 'Stays Hidden' is a hover tooltip ([hint]) carrying the rewritten glossary help.
var p = tree.current_scene._ai_suggestion_panel
var built = p.build_breakdown(p._decision, p._meta, {}, true)
var rx = RegEx.new()
rx.compile("\\[url=(opt:[0-9]+:[0-9]+)\\]")
var keys = []
for m in rx.search_all(str(built.bbcode)):
	var key = m.get_string(1)
	if not key in keys:
		keys.append(key)
for key in keys:
	if not bool(p._expanded.get(key, false)):
		p.toggle_section(key)
var now = p.build_breakdown(p._decision, p._meta, p._expanded, false)
var help = AIReasoningGlossary.help("hidden_gain")
var want = "[hint=\"" + help.replace("\"", "'").replace("]", ")").replace("[", "(") + "\"]Stays Hidden[/hint]"
return keys.size() > 0 and help.contains("will be Hidden in the enemy's next turn (in light or dense terrain, and its last shots no longer count by then)") and str(now.bbcode).contains(want) and p.breakdown_text.contains("Stays Hidden")

# Bring the 'Stays Hidden' row into view in the card (the card keeps its scroll
# position across a re-render, so this runs after the toggles settled).
var p = tree.current_scene._ai_suggestion_panel
var lines = str(p.build_breakdown(p._decision, p._meta, p._expanded, false).bbcode).split("\n")
var idx = -1
for i in range(lines.size()):
	if lines[i].contains("]Stays Hidden[/hint]"):
		idx = i
		break
if idx >= 0:
	p._rich.scroll_to_paragraph(maxi(idx - 3, 0))
return idx

# SHIPPED-DEFAULT CHECK: the profile cleared, the same card has no
# 'Stays Hidden' part (WEIGHT_HIDDEN_GAINED ships 0) — the term is the
# profile, nothing else. Then the profile is re-loaded for (b).
AIDecisionMaker.clear_player_profile(1)
var d_off = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var off = 0.0
for r in d_off.get("_ai_decision_records", []):
	for c in r.get("candidates", []):
		var bd = c.get("score_breakdown", {})
		if bd is Dictionary and bd.has("hidden_gain"):
			off = maxf(off, float(bd["hidden_gain"]))
var f = FileAccess.open("res://tests/bench_profiles/yt_findings_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
var d_on = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var on = 0.0
for r in d_on.get("_ai_decision_records", []):
	for c in r.get("candidates", []):
		var bd = c.get("score_breakdown", {})
		if bd is Dictionary and bd.has("hidden_gain"):
			on = maxf(on, float(bd["hidden_gain"]))
return off == 0.0 and on > 0.0

# The SHOOTING case: P2's Prosecutors (INFANTRY) inside area-large-2, ~9"
# south of the squad, with the 13.09 shot record of a ranged attack in THEIR
# last turn (play-order index cur - 1, the stamp every ranged-attack path
# writes): a target now (that shot still counts this turn), Hidden again in
# their next turn (cur + 1) if they hold fire — F003's 'About to regain Hidden'.
var st = GameState.state
var pr = st.units.U_PROSECUTORS_A_P2
var k = 0
for m in pr.models:
	m.position = {"x": 1440.0 + 50.0 * float(k), "y": 700.0}
	k += 1
if not pr.has("flags"):
	pr["flags"] = {}
pr.flags.erase("shot_recently")
pr.flags["last_shot_idx"] = int(GameState.get_player_turn_index()) - 1
var inside = 0
for m in pr.models:
	if TerrainManager.area_at(Vector2(float(m.position.x), float(m.position.y))).get("id", "") == "area-large-2":
		inside += 1
return inside

# ENGINE truth (not the AI's opinion): not Hidden now, Hidden at the next
# play-order turn, and an eligible target of the squad now.
var pr = GameState.state.units.U_PROSECUTORS_A_P2
var cur = int(GameState.get_player_turn_index())
var now_h = 0
var next_h = 0
for m in pr.models:
	if not m.get("alive", true):
		continue
	if TerrainManager.is_model_hidden(m, pr):
		now_h += 1
	if TerrainManager.is_model_hidden_at(m, pr, cur + 1):
		next_h += 1
var elig = RulesEngine.get_eligible_targets("U_CUSTODIAN_GUARD_B", GameState.create_snapshot(), true)
return now_h == 0 and next_h >= 1 and elig.has("U_PROSECUTORS_A_P2")

var d_best = tree.current_scene._ai_suggestion_panel._decision
var best = 0.0
for r in d_best.get("_ai_decision_records", []):
	for c in r.get("candidates", []):
		var bd = c.get("sub_breakdowns", {}).get("target_value", {})
		if bd is Dictionary and bd.has("tv_regains_hidden"):
			best = maxf(best, float(bd["tv_regains_hidden"]))
return best

# Every option's '▸ details' link, through the panel's own handler
# (toggle_section, what clicking the link calls), then the text it now shows:
# 'About to regain Hidden' is a hover tooltip ([hint]) carrying the rewritten glossary help.
var p = tree.current_scene._ai_suggestion_panel
var built = p.build_breakdown(p._decision, p._meta, {}, true)
var rx = RegEx.new()
rx.compile("\\[url=(opt:[0-9]+:[0-9]+)\\]")
var keys = []
for m in rx.search_all(str(built.bbcode)):
	var key = m.get_string(1)
	if not key in keys:
		keys.append(key)
for key in keys:
	if not bool(p._expanded.get(key, false)):
		p.toggle_section(key)
var now = p.build_breakdown(p._decision, p._meta, p._expanded, false)
var help = AIReasoningGlossary.help("tv_regains_hidden")
var want = "[hint=\"" + help.replace("\"", "'").replace("]", ")").replace("[", "(") + "\"]About to regain Hidden[/hint]"
return keys.size() > 0 and help.contains("It will be Hidden in its next turn (in light or dense terrain, its last shots no longer counting by then)") and str(now.bbcode).contains(want) and p.breakdown_text.contains("About to regain Hidden")

# Bring the 'About to regain Hidden' row into view in the card (the card keeps its scroll
# position across a re-render, so this runs after the toggles settled).
var p = tree.current_scene._ai_suggestion_panel
var lines = str(p.build_breakdown(p._decision, p._meta, p._expanded, false).bbcode).split("\n")
var idx = -1
for i in range(lines.size()):
	if lines[i].contains("]About to regain Hidden[/hint]"):
		idx = i
		break
if idx >= 0:
	p._rich.scroll_to_paragraph(maxi(idx - 3, 0))
return idx

# CONTROL: a shot record from THIS turn (index cur) still counts in their
# next turn, so they will NOT regain Hidden then: no such part.
var pr = GameState.state.units.U_PROSECUTORS_A_P2
var keep = int(pr.flags.last_shot_idx)
pr.flags["last_shot_idx"] = int(GameState.get_player_turn_index())
var d_this_turn = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var this_turn = 0.0
for r in d_this_turn.get("_ai_decision_records", []):
	for c in r.get("candidates", []):
		var bd = c.get("sub_breakdowns", {}).get("target_value", {})
		if bd is Dictionary and bd.has("tv_regains_hidden"):
			this_turn = maxf(this_turn, float(bd["tv_regains_hidden"]))
pr.flags["last_shot_idx"] = keep
return this_turn

# SHIPPED-DEFAULT CHECK: the profile cleared (HIDDEN_WINDOW_BONUS ships
# 1.0), the same target carries no 'regains Hidden' part.
AIDecisionMaker.clear_player_profile(1)
var d_best = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var best = 0.0
for r in d_best.get("_ai_decision_records", []):
	for c in r.get("candidates", []):
		var bd = c.get("sub_breakdowns", {}).get("target_value", {})
		if bd is Dictionary and bd.has("tv_regains_hidden"):
			best = maxf(best, float(bd["tv_regains_hidden"]))
return best
